// Constant-time comparison, mirroring draft-generation.json's "Verify secret"
// node (same threat model: a shared secret over a public n8n webhook).
// ponytail: skips that node's cooldown/rate-limit escalation -- this
// endpoint has no LLM-cost abuse vector to guard against, just an
// unauthenticated write of one calendar event per call. Add a cooldown if
// this webhook URL ever leaks and gets hammered.
try {
  const crypto = require('crypto');
  const item = $json || {};
  const headers = item.headers || {};
  const providedSecret = headers['x-calendar-push-webhook-secret'] || '';
  const expectedSecret = $env.CALENDAR_PUSH_WEBHOOK_SECRET || '';

  const providedHash = crypto.createHash('sha256').update(String(providedSecret)).digest();
  const expectedHash = crypto.createHash('sha256').update(String(expectedSecret)).digest();
  const isValid = Boolean(expectedSecret) && Boolean(providedSecret) &&
    crypto.timingSafeEqual(providedHash, expectedHash);

  if (!isValid) {
    return { json: { authFailed: true } };
  }

  const body = item.body || {};
  return {
    json: {
      authFailed: false,
      task_id: body.task_id,
      text: typeof body.text === 'string' ? body.text : '',
      due_at: body.due_at || null,
      starts_at: body.starts_at || null,
      duration_minutes: Number.isFinite(body.duration_minutes) ? body.duration_minutes : null,
    },
  };
} catch (err) {
  return { json: { authFailed: true, error: (err && err.message) || 'Unknown auth error' } };
}

// Builds the Google Calendar event body. A task always has at least one of
// due_at/starts_at -- POST /api/action-items only calls this webhook when
// that's true -- but this stays defensive since the webhook is a public URL.
const t = $json;
const start = t.starts_at || t.due_at;
if (!start) {
  return { json: { skip: true } };
}

const startMs = new Date(start).getTime();
// starts_at (a real scheduled slot) uses its own duration; due_at (a
// deadline, not a slot) gets a short 15-minute marker rather than a
// fabricated block of "work time" on the calendar.
const durationMinutes = t.starts_at ? (t.duration_minutes || 30) : 15;
const endMs = startMs + durationMinutes * 60000;

return {
  json: {
    skip: false,
    task_id: t.task_id,
    event: {
      summary: t.text,
      start: { dateTime: new Date(startMs).toISOString(), timeZone: 'Asia/Colombo' },
      end: { dateTime: new Date(endMs).toISOString(), timeZone: 'Asia/Colombo' },
    },
  },
};
